using System;using System.IO;using System.Linq;using System.Drawing;using System.Collections.Generic;using System.Windows.Forms;using SWBodyOrganizer;
namespace MasterMiao.Weld {
 public sealed class WeldModule:IWorkspaceModule {WeldView view;public string Id{get{return "weld-groups";}}public string Title{get{return "焊接体分组";}}public Control View{get{return view??(view=new WeldView());}}public bool IsBusy{get{return false;}}public bool CanClose(){return true;}public void Dispose(){if(view!=null)view.Dispose();}}
 public sealed class WeldView:UserControl {
  readonly WeldBridge bridge;readonly ListView groups=new ListView{Dock=DockStyle.Fill,View=System.Windows.Forms.View.Details,FullRowSelect=true,HideSelection=false,MultiSelect=true};readonly ListView members=new ListView{Dock=DockStyle.Fill,View=System.Windows.Forms.View.Details,FullRowSelect=true,HideSelection=false,MultiSelect=true};
