   title.AutoSize=false;title.Location=new Point(18,42);title.Size=new Size(610,26);title.Padding=Padding.Empty;title.ForeColor=Color.FromArgb(75,81,90);title.Text="连接装配体 → 创建组 → 选择零件加入";hero.Controls.Add(title);
   var connect=ButtonFor("连接当前装配体",()=>{bridge.Attach();if(markerSize!=null){int saved=(int)bridge.Project.MarkerSizePoints;markerSize.SelectedIndex=saved==10?0:saved==16?2:saved==20?3:1;}title.Text=Path.GetFileName(bridge.Project.AssemblyPath)+"  ·  "+bridge.Project.Configuration;RefreshGroups();int n=bridge.SyncMarkers();status.Text="已连接并刷新标记 · 未解析 "+n+" 项。标记随装配体保存，分组独立自动保存。";},true);connect.Dock=DockStyle.Right;connect.Width=160;hero.Controls.Add(connect);layout.Controls.Add(hero,0,0);
   var tools=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false,AutoScroll=true,Margin=Padding.Empty};Add(tools,"＋ 加入 SW 选中零件",AddSelected,true);Add(tools,"导出所选组",ExportSelected,true);Add(tools,"邻近零件建议",SuggestGroups);Add(tools,"移出当前组",RemoveSelected);Add(tools,"清除高亮",()=>bridge.ClearHighlight());
   var more=new ContextMenuStrip();more.Items.Add("隐藏所选零件",null,(s,e)=>Do(()=>bridge.HideMembers(SelectedMembers())));more.Items.Add("恢复临时隐藏",null,(s,e)=>Do(()=>bridge.RestoreHidden()));more.Items.Add("删除所选组",null,(s,e)=>Do(DeleteGroups));var moreButton=ButtonFor("更多操作 ▾",()=>{},false);moreButton.Click+=(s,e)=>more.Show(moreButton,new Point(0,moreButton.Height));tools.Controls.Add(moreButton);layout.Controls.Add(tools,0,1);
   var split=new SplitContainer{Dock=DockStyle.Fill,Width=1000,SplitterDistance=310,BackColor=BackColor,SplitterWidth=12,Panel1MinSize=240,Panel2MinSize=280};
