   var right=new Panel{Dock=DockStyle.Fill,BackColor=Color.White,Padding=new Padding(14)};var memberHelp=new Label{Dock=DockStyle.Top,Height=42,Text="组内零件   /   点击定位高亮 · 同一零件可以加入多个组",ForeColor=Color.FromArgb(71,85,105),Padding=new Padding(0,8,0,0)};right.Controls.Add(members);right.Controls.Add(memberHelp);
   groups.Columns.Add("编号 / 焊接组",175);groups.Columns.Add("数量",45);groups.Columns.Add("标记",48);members.Columns.Add("零件实例",280);members.Columns.Add("全部所属组",210);members.Columns.Add("配置",110);
   foreach(var list in new[]{groups,members}){list.BorderStyle=BorderStyle.None;list.BackColor=Color.White;list.ForeColor=Color.FromArgb(30,41,59);list.Font=new Font("Microsoft YaHei UI",10);list.SmallImageList=new ImageList{ImageSize=new Size(1,34)};list.SmallImageList.Images.Add(new Bitmap(1,34));}
