   var foot=new Panel{Dock=DockStyle.Fill,BackColor=Color.White,Padding=new Padding(8),Margin=new Padding(0,10,0,0)};var display=new FlowLayoutPanel{Dock=DockStyle.Top,Height=46,WrapContents=false,AutoScroll=true};Add(display,"◈ 显示全部标记",()=>Markers(true,true),true);Add(display,"隐藏全部标记",()=>Markers(false,true));Add(display,"显示所选",()=>Markers(true));Add(display,"隐藏所选",()=>Markers(false));Add(display,"刷新位置 / 样式",()=>{int n=bridge.SyncMarkers();status.Text="标记已刷新 · 未解析 "+n+" 项。请保存装配体。";});display.Controls.Add(new Label{Text="标牌大小",AutoSize=true,Margin=new Padding(12,11,4,0)});var size=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=76,Margin=new Padding(3,7,3,3)};markerSize=size;size.Items.AddRange(new object[]{"小","标准","大","加大"});size.SelectedIndex=1;size.SelectionChangeCommitted+=(s,e)=>Do(()=>{bridge.Guard();bridge.Project.MarkerSizePoints=new[]{10d,12d,16d,20d}[size.SelectedIndex];bridge.SyncMarkers();status.Text="标牌大小已更新，请保存装配体。";});display.Controls.Add(size);foot.Controls.Add(status);foot.Controls.Add(display);status.ForeColor=Color.FromArgb(71,85,105);status.Padding=new Padding(6,8,6,0);layout.Controls.Add(foot,0,3);Controls.Add(layout);
   groups.SelectedIndexChanged+=(s,e)=>{if(refreshing)return;Do(()=>{RefreshMembers();var selected=ChosenGroups();if(selected.Count>0){int n=bridge.Highlight(selected);status.Text="已高亮 "+selected.Count+" 组 · 未解析 "+n+" 项。共享成员保留多个编号；高亮使用六种选择色。";}else bridge.ClearHighlight();});};members.SelectedIndexChanged+=(s,e)=>{if(refreshing||members.SelectedItems.Count==0)return;Do(()=>bridge.Highlight(ChosenGroups(),SelectedMembers().Select(x=>x.Id)));};groups.ContextMenuStrip=Menu(groups,true);members.ContextMenuStrip=Menu(members,false);
  }
  Button ButtonFor(string text,Action action,bool primary){var b=new Button{Text=text,AutoSize=true,Height=36,MinimumSize=new Size(70,36),FlatStyle=FlatStyle.Flat,BackColor=primary?Color.FromArgb(215,25,32):Color.FromArgb(246,248,251),ForeColor=primary?Color.White:Color.FromArgb(44,62,80),Padding=new Padding(10,3,10,3),Margin=new Padding(0,3,8,3),Cursor=Cursors.Hand};b.FlatAppearance.BorderSize=0;b.Click+=(s,e)=>Do(action);return b;}
  void Add(FlowLayoutPanel p,string text,Action action,bool primary=false){p.Controls.Add(ButtonFor(text,action,primary));}

  void Do(Action action){try{action();}catch(Exception ex){status.Text=ex.GetBaseException().Message;}}
  List<WeldGroup> ChosenGroups(){bridge.Guard();return groups.SelectedItems.Cast<ListViewItem>().Select(x=>(WeldGroup)x.Tag).ToList();}
  WeldGroup One(){var list=ChosenGroups();if(list.Count!=1)throw new InvalidOperationException("请选择一个焊接组。");return list[0];}
  List<WeldMember> SelectedMembers(){return members.SelectedItems.Cast<ListViewItem>().Select(x=>(WeldMember)x.Tag).ToList();}
  int NextColor(){int[] colors={0xD07020,0x30A040,0x4060E0,0xC050B0,0x20B0D0,0xD0B030,0x8070E0,0x70A090};return colors.FirstOrDefault(c=>!bridge.Project.Groups.Any(g=>g.Color==c));}
  bool EditDialog(string caption,ref string name,ref int color,ref string remark,ref string number){
   using(var dialog=new Form{Text=caption,Width=560,Height=340,Font=Font,StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false,BackColor=Color.White}){
    var input=new TextBox{Text=name,Left=90,Top=24,Width=290};var labelNumber=new TextBox{Text=number,Left=90,Top=70,Width=110,MaxLength=6};var notes=new TextBox{Text=remark,Left=90,Top=116,Width=290};
    var preview=new PictureBox{Left=410,Top=28,Width=90,Height=130,SizeMode=PictureBoxSizeMode.Zoom,BackColor=Color.FromArgb(232,238,245)};
    int chosen=color;Action refreshPreview=()=>{var previous=preview.Image;preview.Image=WeldBadge.Draw(labelNumber.Text,chosen);if(previous!=null)previous.Dispose();};labelNumber.TextChanged+=(s,e)=>refreshPreview();
    var swatch=new Button{Text="标牌填充色",Left=90,Top=164,Width=140,Height=35,BackColor=ColorTranslator.FromWin32(color)};swatch.Click+=(s,e)=>{using(var picker=new ColorDialog{Color=swatch.BackColor,FullOpen=true})if(picker.ShowDialog(dialog)==DialogResult.OK){chosen=ColorTranslator.ToWin32(picker.Color);swatch.BackColor=picker.Color;refreshPreview();}};
    var error=new Label{Left=90,Top=207,Width=430,Height=30,ForeColor=Color.Firebrick};var ok=new Button{Text="保存",Left=310,Top=250,Width=90,Height=32};ok.Click+=(s,e)=>{try{WeldBadge.ValidateNumber(labelNumber.Text);dialog.DialogResult=DialogResult.OK;}catch(Exception ex){error.Text=ex.Message;}};
    dialog.Controls.AddRange(new Control[]{new Label{Text="组名称",Left=18,Top=27,Width=65},input,new Label{Text="标牌数字",Left=18,Top=73,Width=70},labelNumber,new Label{Text="备注",Left=18,Top=119,Width=65},notes,swatch,preview,new Label{Text="透明背景预览",Left=400,Top=170,Width=125},error,ok,new Button{Text="取消",Left=410,Top=250,Width=90,Height=32,DialogResult=DialogResult.Cancel}});dialog.AcceptButton=ok;refreshPreview();bool accepted=dialog.ShowDialog(this)==DialogResult.OK;if(preview.Image!=null)preview.Image.Dispose();if(!accepted)return false;name=input.Text.Trim();remark=notes.Text;color=chosen;number=labelNumber.Text.Trim();return true;
   }
  }
  void NewGroup(){bridge.Guard();string name="焊接组 "+bridge.Project.NextNumber,remark="",number=bridge.Project.NextNumber.ToString();int color=NextColor();if(!EditDialog("新建焊接组",ref name,ref color,ref remark,ref number))return;var g=WeldStore.AddGroup(bridge.Project,name,color);g.Remark=remark;g.BadgeNumber=number;bridge.Save();RefreshGroups(g.Id);}
  void EditGroup(){var g=One();string name=g.Name,remark=g.Remark,number=WeldBadge.Label(g);int color=g.Color;if(!EditDialog("编辑 "+WeldBadge.Label(g),ref name,ref color,ref remark,ref number))return;if(name.Length==0||bridge.Project.Groups.Any(x=>x.Id!=g.Id&&(x.Name.Equals(name,StringComparison.OrdinalIgnoreCase)||x.Color==color)))throw new InvalidOperationException("名称为空、名称重复或颜色已被其他组使用。");g.Name=name;g.Color=color;g.Remark=remark;g.BadgeNumber=number;bridge.Save();bridge.SyncMarkers();RefreshGroups(g.Id);}
  void AddSelected(){var g=One();var selected=bridge.Selected();foreach(var m in selected)WeldStore.AddMember(g,m);bridge.Save();int missing=bridge.SyncMarkers();RefreshGroups(g.Id);status.Text="已加入 "+selected.Count+" 个零件；组内自动去重，其他组归属保留。未解析 "+missing+" 项。";}
  void RemoveSelected(){var g=One();var ids=SelectedMembers().Select(m=>m.Id).ToArray();bridge.RemoveMembers(g,ids);RefreshGroups(g.Id);}
  void DeleteGroups(){var list=ChosenGroups();if(list.Count==0)return;if(MessageBox.Show(this,"删除所选 "+list.Count+" 个组及其小标记？不会删除零件或其他组归属。","删除焊接组",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;bridge.RemoveGroups(list.Select(g=>g.Id));RefreshGroups();}
  void Markers(bool visible,bool all=false){var selected=ChosenGroups().Select(g=>g.Id).ToArray();var ids=all?bridge.Project.Groups.Select(g=>g.Id).ToArray():selected;if(ids.Length==0)throw new InvalidOperationException("请先选择焊接组。");int missing=bridge.SetMarkerVisibility(ids,visible);RefreshGroups();refreshing=true;try{foreach(ListViewItem row in groups.Items)row.Selected=selected.Contains(((WeldGroup)row.Tag).Id);}finally{refreshing=false;}RefreshMembers();status.Text="已"+(visible?"显示":"隐藏")+ids.Length+" 组标记；分组归属和孔标注保持不变。请保存装配体。"+(missing>0?" 未找到 "+missing+" 个标记，可刷新重建。":"");}
  void ExportSelected(){var selected=ChosenGroups();if(selected.Count==0)throw new InvalidOperationException("请先选择要导出的焊接组。");using(var dialog=new Form{Text="导出 "+selected.Count+" 个焊接组",Width=590,Height=300,Font=Font,StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false}){var folder=new TextBox{Left=20,Top=38,Width=440,Text=Path.Combine(Path.GetDirectoryName(bridge.Project.AssemblyPath),"焊接组装配体")};var browse=new Button{Text="选择…",Left=470,Top=36,Width=80};browse.Click+=(s,e)=>{using(var picker=new FolderBrowserDialog{SelectedPath=folder.Text,Description="选择焊接组导出位置"})if(picker.ShowDialog(dialog)==DialogResult.OK)folder.Text=picker.SelectedPath;};var reference=new Label{Text="继续引用源零件，不生成零件副本。",AutoSize=true,Left=20,Top=85};var step=new CheckBox{Text="同时导出该焊接组的 STEP 模型",AutoSize=true,Left=20,Top=122};var ok=new Button{Text="开始导出",Left=350,Top=210,Width=95,Height=32,DialogResult=DialogResult.OK};dialog.Controls.AddRange(new Control[]{new Label{Text="每组建立独立文件夹，同名文件夹自动另建，不覆盖旧文件。",Left=20,Top=10,Width=530},folder,browse,reference,step,new Label{Text="仅导出已保存、已解析的零件；保留当前位置和配置。",Left=20,Top=164,Width=530},ok,new Button{Text="取消",Left=455,Top=210,Width=95,Height=32,DialogResult=DialogResult.Cancel}});dialog.AcceptButton=ok;if(dialog.ShowDialog(this)!=DialogResult.OK)return;UseWaitCursor=true;try{status.Text="喵师傅正在施工 · 正在导出焊接组…";status.Refresh();var results=bridge.ExportGroups(selected.Select(g=>g.Id),new WeldExportOptions{Folder=folder.Text,Step=step.Checked});status.Text="已完成 "+results.Count+" 个焊接组，位置："+Path.GetFullPath(folder.Text);}finally{UseWaitCursor=false;}}}
  void SuggestGroups(){var group=One();var selected=bridge.Selected();if(selected.Count!=1)throw new InvalidOperationException("自动建议请先在 SolidWorks 中选择一个基准零件。");var seed=selected[0];using(var dialog=new Form{Text="以 "+seed.Instance+" 为基准查找候选",Width=850,Height=540,StartPosition=FormStartPosition.CenterParent}){var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=75};var gap=new NumericUpDown{DecimalPlaces=2,Minimum=0,Maximum=10,Value=.2m,Width=75};var excluded=new TextBox{Text="螺钉,螺栓,螺母,垫圈,轴承,screw,bolt,nut,washer,bearing",Width=340};var scan=new Button{Text="查找邻近零件",AutoSize=true};bar.Controls.AddRange(new Control[]{new Label{Text="允许间隙(mm)",AutoSize=true,Padding=new Padding(3,6,0,0)},gap,new Label{Text="排除名称关键词",AutoSize=true,Padding=new Padding(3,6,0,0)},excluded,scan});var list=new ListView{Dock=DockStyle.Fill,View=System.Windows.Forms.View.Details,CheckBoxes=true,FullRowSelect=true};list.Columns.Add("候选零件",290);list.Columns.Add("间隙(mm)",100);list.Columns.Add("判断依据",330);var footer=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=70};var add=new Button{Text="确认加入当前组",AutoSize=true,Enabled=false};var hint=new Label{Text="只查找与基准零件直接邻近的候选，不沿接触链自动合并。请勾选确认；基准零件会一同加入。",AutoSize=true};footer.Controls.Add(hint);footer.SetFlowBreak(hint,true);footer.Controls.Add(add);var all=new Button{Text="全选",AutoSize=true};all.Click+=(s,e)=>{foreach(ListViewItem row in list.Items)row.Checked=true;};footer.Controls.Add(all);var none=new Button{Text="全不选",AutoSize=true};none.Click+=(s,e)=>{foreach(ListViewItem row in list.Items)row.Checked=false;};footer.Controls.Add(none);scan.Click+=(s,e)=>{scan.Enabled=false;try{list.Items.Clear();foreach(var candidate in bridge.Suggest(seed,(double)gap.Value,excluded.Text)){var row=new ListViewItem(candidate.Member.Instance){Tag=candidate};row.SubItems.Add(candidate.GapMm.ToString("0.000"));row.SubItems.Add(candidate.Reason);list.Items.Add(row);}hint.Text="找到 "+list.Items.Count+" 个候选。距离不能证明焊接关系，请勾选确认；基准零件会一同加入。";add.Enabled=true;}catch(Exception ex){hint.Text=ex.GetBaseException().Message;}finally{scan.Enabled=true;}};list.SelectedIndexChanged+=(s,e)=>{if(list.SelectedItems.Count==0)return;Do(()=>{var temp=new WeldGroup{Members=list.SelectedItems.Cast<ListViewItem>().Select(x=>((WeldCandidate)x.Tag).Member).ToList()};bridge.Highlight(new[]{temp});});};add.Click+=(s,e)=>{try{bridge.Guard();WeldStore.AddMember(group,seed);foreach(ListViewItem row in list.CheckedItems)WeldStore.AddMember(group,((WeldCandidate)row.Tag).Member);bridge.Save();bridge.SyncMarkers();dialog.DialogResult=DialogResult.OK;}catch(Exception ex){hint.Text=ex.GetBaseException().Message;}};dialog.Controls.Add(list);dialog.Controls.Add(footer);dialog.Controls.Add(bar);dialog.ShowDialog(this);RefreshGroups(group.Id);}}
  void RefreshGroups(string select=null){refreshing=true;try{groups.Items.Clear();foreach(var g in bridge.Project.Groups){var item=new ListViewItem(WeldBadge.Label(g)+"  "+g.Name){Tag=g,ForeColor=ColorTranslator.FromWin32(g.Color)};item.SubItems.Add(g.Members.Count.ToString());item.SubItems.Add(g.MarkersVisible?"显示":"隐藏");groups.Items.Add(item);if(g.Id==select)item.Selected=true;}}finally{refreshing=false;}RefreshMembers();}
  void RefreshMembers(){refreshing=true;try{members.Items.Clear();var selected=groups.SelectedItems.Cast<ListViewItem>().Select(x=>(WeldGroup)x.Tag);foreach(var m in selected.SelectMany(g=>g.Members).GroupBy(m=>m.Id).Select(g=>g.First())){var item=new ListViewItem(m.Instance){Tag=m};item.SubItems.Add(string.Join("、",bridge.Project.Groups.Where(g=>g.Members.Any(x=>x.Id==m.Id)).Select(g=>WeldBadge.Label(g))));item.SubItems.Add(m.Configuration);members.Items.Add(item);}}finally{refreshing=false;}}
  ContextMenuStrip Menu(ListView list,bool isGroup){var menu=new ContextMenuStrip();foreach(var text in new[]{"全选","全不选","反选"}){var item=new ToolStripMenuItem(text);item.Click+=(s,e)=>{refreshing=true;try{foreach(ListViewItem row in list.Items)row.Selected=text=="全选"||(text=="反选"&&!row.Selected);}finally{refreshing=false;}Do(()=>{if(isGroup){RefreshMembers();bridge.Highlight(ChosenGroups());}else bridge.Highlight(ChosenGroups(),SelectedMembers().Select(m=>m.Id));});};menu.Items.Add(item);}if(isGroup){menu.Items.Add(new ToolStripSeparator());menu.Items.Add("显示所选组标记",null,(s,e)=>Do(()=>Markers(true)));menu.Items.Add("隐藏所选组标记",null,(s,e)=>Do(()=>Markers(false)));}var remove=new ToolStripMenuItem(isGroup?"删除所选组":"移出当前组");remove.Click+=(s,e)=>Do(isGroup?(Action)DeleteGroups:RemoveSelected);menu.Items.Add(remove);return menu;}
  protected override void Dispose(bool disposing){if(disposing)bridge.Dispose();base.Dispose(disposing);}
 }
